parameters.jsCode:
const items = $input.all();

const ctx = $('Extract error context').first().json;
const client = (ctx.asanaClient || '').trim().toLowerCase();
const assignee = (ctx.asanaAssignee || '').trim().toLowerCase();

const projects = items.filter(i => i.json.resource_type === 'project');
const users = items.filter(i => i.json.resource_type === 'user');

const matchedProject = client
  ? projects.find(i => (i.json.name || '').trim().toLowerCase() === client)
  : null;

const matchedUser = assignee
  ? users.find(i => {
      const fullName = (i.json.name || '').trim().toLowerCase();
      const words = assignee.split(' ').filter(w => w.length > 0);
      return words.every(w => fullName.includes(w));
    })
  : null;

const missing = [];
if (!matchedProject) missing.push('project');
if (!matchedUser) missing.push('user');

return [{
  json: {
    projectGid: matchedProject ? matchedProject.json.gid : null,
    projectName: matchedProject ? matchedProject.json.name : null,
    userGid: matchedUser ? matchedUser.json.gid : null,
    userName: matchedUser ? matchedUser.json.name : null,
    workflowName: ctx.workflowName,
    workflowId: ctx.workflowId,
    executionId: ctx.executionId,
    executionMode: ctx.executionMode,
    lastNode: ctx.lastNode,
    errorMessage: ctx.errorMessage,
    executionUrl: ctx.executionUrl,
    asanaClient: ctx.asanaClient,
    asanaAssignee: ctx.asanaAssignee,
    resolveError: missing.length ? 'Missing: ' + missing.join(', ') : null
  }
}];

const searchResults = $input.all();
const rg = $('Match Asana project and user').first().json;

const matchedTask = searchResults.find(i => i.json.gid);
const isDuplicate = !!matchedTask;

return [{
  json: {
    isDuplicate,
    existingTaskGid: isDuplicate ? matchedTask.json.gid : null,
    projectGid: rg.projectGid,
    projectName: rg.projectName,
    userGid: rg.userGid,
    userName: rg.userName,
    workflowName: rg.workflowName,
    workflowId: rg.workflowId,
    executionId: rg.executionId,
    executionMode: rg.executionMode,
    lastNode: rg.lastNode,
    errorMessage: rg.errorMessage,
    executionUrl: rg.executionUrl,
    asanaClient: rg.asanaClient,
    asanaAssignee: rg.asanaAssignee,
    resolveError: rg.resolveError
  }
}];

