parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "root_cause": {
      "type": "string",
      "description": "One sentence explaining WHY the error happened, not just restating the message"
    },
    "solution": {
      "type": "string",
      "description": "Specific actionable fix naming the exact node, field, or setting to change"
    },
    "steps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 2,
      "maxItems": 4,
      "description": "2-4 concrete actions each starting with an action verb"
    },
    "severity": {
      "type": "string",
      "enum": [
        "Critical",
        "High",
        "Medium",
        "Low"
      ]
    },
    "error_category": {
      "type": "string",
      "enum": [
        "unicode",
        "credential",
        "network",
        "logic",
        "configuration",
        "parsing"
      ]
    }
  },
  "required": [
    "root_cause",
    "solution",
    "steps",
    "severity",
    "error_category"
  ]
}

parameters.jsCode:
const output = $json.output;
const cd = $('Check Duplicate?').first().json;
const cfg = $('Configuration').first().json;

const daysMap = { 'Critical': 0, 'High': 1, 'Medium': 3, 'Low': 7 };
const days = daysMap[output.severity] ?? 3;

const offsetHours = Number(cfg.timezoneOffsetHours) || 0;
const dueDate = new Date(Date.now() + offsetHours * 60 * 60 * 1000);
dueDate.setDate(dueDate.getDate() + days);
const due_on = dueDate.toISOString().split('T')[0];

return [{
  json: {
    root_cause: output.root_cause,
    solution: output.solution,
    steps: output.steps,
    severity: output.severity,
    error_category: output.error_category,
    due_on,
    projectGid: cd.projectGid,
    projectName: cd.projectName,
    userGid: cd.userGid,
    userName: cd.userName,
    workflowName: cd.workflowName,
    workflowId: cd.workflowId,
    executionId: cd.executionId,
    executionMode: cd.executionMode,
    lastNode: cd.lastNode,
    errorMessage: cd.errorMessage,
    executionUrl: cd.executionUrl,
    asanaClient: cd.asanaClient,
    asanaAssignee: cd.asanaAssignee,
    resolveError: cd.resolveError
  }
}];

